import{_ as a,o as t,c as i,a8 as d}from"./chunks/framework.CiGKN4gy.js";const p=JSON.parse('{"title":"Current","description":"","frontmatter":{"title":"Current","lang":"en"},"headers":[],"relativePath":"changes/current.md","filePath":"changes/current.md","lastUpdated":1790353258000}'),o={name:"changes/current.md"};function r(l,e,c,h,n,s){return t(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjJDdXJyZW50JTIyJTJDJTIybGFuZyUyMiUzQSUyMmVuJTIyJTJDJTIyZGF0ZSUyMiUzQTE3OTAzNTMyNTgwMDAlN0Q="},[...e[0]||(e[0]=[d('<h1 id="change-log-current" tabindex="-1">Change Log (Current) <a class="header-anchor" href="#change-log-current" aria-label="Permalink to &quot;Change Log (Current)&quot;">​</a></h1><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><div class="tip custom-block"><p class="custom-block-title">What is a breaking change?</p><ul><li>The old configuration file may not work, for example, if a directive item is removed or renamed.</li></ul></div><h2 id="unreleased" tabindex="-1">[Unreleased] <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><hr><h2 id="_10-1-2-2022-07-09-utc-0800" tabindex="-1">[10.1.2] - 2022-07-09 UTC+0800 <a class="header-anchor" href="#_10-1-2-2022-07-09-utc-0800" aria-label="Permalink to &quot;[10.1.2] - 2022-07-09 UTC+0800&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>compatible with <code>nginx-1.23.0</code></li></ul><hr><h2 id="_10-1-1-2022-01-07-utc-0800" tabindex="-1">[10.1.1] - 2022-01-07 UTC+0800 <a class="header-anchor" href="#_10-1-1-2022-01-07-utc-0800" aria-label="Permalink to &quot;[10.1.1] - 2022-01-07 UTC+0800&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>PCRE2 library support.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Memory leak.</p></li><li><p>CAPTCHA and Under-Attack-Mode sometimes cause infinite page refreshes.</p></li></ul><hr><h2 id="_10-1-0-2021-12-14-utc-0800" tabindex="-1">[10.1.0] - 2021-12-14 UTC+0800 <a class="header-anchor" href="#_10-1-0-2021-12-14-utc-0800" aria-label="Permalink to &quot;[10.1.0] - 2021-12-14 UTC+0800&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>You can set the directive <code>waf</code> to <code> bypass</code>, in which case no requests will be intercepted, but ngx_waf will still do the detection and logging.</p></li><li><p>The directive <code>waf_verify_bot</code> has a new parameter <code>SogouSpider</code>, which is used to verify if it is a Sogou crawler.</p></li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Garbage collection is not running, which does not lead to memory leaks, but does lead to performance problems.</p></li><li><p>Sometimes the <code>[FAKE-BOT]</code> log is printed incorrectly.</p></li></ul><hr><h2 id="_10-0-1-2021-12-05-utc-0800" tabindex="-1">[10.0.1] - 2021-12-05 UTC+0800 <a class="header-anchor" href="#_10-0-1-2021-12-05-utc-0800" aria-label="Permalink to &quot;[10.0.1] - 2021-12-05 UTC+0800&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added two Easter eggs, which you can find clues in the documentation. These two eggs are not triggered automatically and need to be enabled manually.</li></ul><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>All parameters of the directive <code>waf_mode</code> corresponding to the request method are not working.</li></ul><hr><h2 id="_10-0-0-2021-11-30-utc-0800" tabindex="-1">[10.0.0] - 2021-11-30 UTC+0800 <a class="header-anchor" href="#_10-0-0-2021-11-30-utc-0800" aria-label="Permalink to &quot;[10.0.0] - 2021-11-30 UTC+0800&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>New directive <code>waf_zone</code>, used to declare a piece of shared memory that will be used for other directives, such as <code>waf_cc_deny</code>.</p></li><li><p>New directive <code>waf_action</code>, used to set actions after intercepting a request, such as returning a specific status code or challenging the client with a captcha.</p></li><li><p>New directive <code>waf_block_page</code>, used to set the blocking page to return the specified HTML file when the request is blocked.</p></li><li><p>A new embedded variable, <code>$waf_rate</code>, is used to indicate the number of accesses to the current IP in a period. The period is determined by the parameter <code>rate</code> of the directive <code>waf_cc_deny</code>, or by the parameter <code>duration</code> if the IP has been blacked out.</p></li><li><p>The directive <code>waf_captcha</code> has a new parameter <code>max_fails</code>, which sets the maximum number of attempts for the captcha and the blocking time after it is exceeded.</p></li><li><p>The directive <code>waf_captcha</code> has a new parameter <code>zone</code> that specifies a piece of shared memory, which needs to be set if and only if the parameter <code>max_fails</code> is set.</p></li><li><p>The directive <code>waf_captcha</code> has a new parameter <code>sitekey</code>, which needs to be set if and only if the parameter <code>file</code> is omitted.</p></li><li><p>When you reload nginx, the module keeps as much information in shared memory as possible so that it is not emptied, such as statistics used by CC protection.</p></li></ul><h3 id="removed-1" tabindex="-1">Removed <a class="header-anchor" href="#removed-1" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><p>The directive <code>waf_http_status</code> has been removed and the related features have been merged into the directive <code>waf_action</code>.</p></li><li><p>The parameter <code>size</code> of the directive <code>waf_cc_deny</code> has been removed and <code>zone</code> is now used instead.</p></li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p>You can omit the parameter <code>file</code> of the directive <code>waf_under_attack</code>; omitting this parameter will use a built-in file from <code>assets/under_attack.html</code>.</p></li><li><p>You can omit the argument <code>file</code> to the directive <code>waf_captcha</code>, which when omitted will use a built-in file based on the value of the argument <code>prov</code>, which comes from the directory <code>assets/</code>.</p></li></ul><hr><h2 id="_9-0-6-2021-10-10-utc-0800" tabindex="-1">[9.0.6] - 2021-10-10 UTC+0800 <a class="header-anchor" href="#_9-0-6-2021-10-10-utc-0800" aria-label="Permalink to &quot;[9.0.6] - 2021-10-10 UTC+0800&quot;">​</a></h2><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>If the directive <code>try_files</code> is executed, CAPTCHA may fail.</li></ul><hr><h2 id="_9-0-5-2021-10-09-utc-0800" tabindex="-1">[9.0.5] - 2021-10-09 UTC+0800 <a class="header-anchor" href="#_9-0-5-2021-10-09-utc-0800" aria-label="Permalink to &quot;[9.0.5] - 2021-10-09 UTC+0800&quot;">​</a></h2><h3 id="new-test-suite" tabindex="-1">New test suite <a class="header-anchor" href="#new-test-suite" aria-label="Permalink to &quot;New test suite&quot;">​</a></h3><p>By chance, I found a test suite: <a href="https://github.com/openresty/test-nginx" target="_blank" rel="noreferrer">test-nginx</a>. It looked great, so I wrote a lot of test cases and tested with it. <del>Un</del>fortunately I found a lot of bugs, very wise of me.</p><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p>Removed useless debug log.</p></li><li><p>More debug log.</p></li></ul><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Sometimes the connection is closed prematurely.</p></li><li><p>When CAPTCHA is enabled, the request body inspection may be wrong.</p></li><li><p>CAPTCHA may fail due to HTTP caching.</p></li><li><p>Memory leak when reloading nginx.</p></li><li><p>Failed to properly merge directive <code>waf_cache</code> from different contexts.</p></li><li><p>Failed to properly merge directives <code>waf_cc_deny</code> from different contexts.</p></li><li><p>Failed to inherit <code>Referer</code> blacklist different contexts.</p></li><li><p>Failed to properly handle incorrect command syntax.</p></li><li><p>Fixed a default rule of URL.</p></li><li><p>Fixed the following files so that the page can be refreshed automatically after the CAPTCHA is completed.</p><ul><li><code>assets/hCaptcha.html</code></li><li><code>assets/reCAPTCHAv2_Checkbox.html</code></li><li><code>assets/reCAPTCHAv2_Invisible.html</code></li><li><code>assets/reCAPTCHAv3.html</code></li></ul></li></ul><hr><h2 id="_9-0-4-2021-09-29-utc-0800" tabindex="-1">[9.0.4] - 2021-09-29 UTC+0800 <a class="header-anchor" href="#_9-0-4-2021-09-29-utc-0800" aria-label="Permalink to &quot;[9.0.4] - 2021-09-29 UTC+0800&quot;">​</a></h2><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>All inspections are incorrectly skipped when the directive <code>rewrite</code> causes an internal redirect.</li></ul><hr><h2 id="_9-0-3-2021-09-28-utc-0800" tabindex="-1">[9.0.3] - 2021-09-28 UTC+0800 <a class="header-anchor" href="#_9-0-3-2021-09-28-utc-0800" aria-label="Permalink to &quot;[9.0.3] - 2021-09-28 UTC+0800&quot;">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>More debug logs.</li></ul><h3 id="fixed-8" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-8" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Failed to display the CAPTCHA page.</li></ul><hr><h2 id="_9-0-2-2021-09-25-utc-0800" tabindex="-1">[9.0.2] - 2021-09-25 UTC+0800 <a class="header-anchor" href="#_9-0-2-2021-09-25-utc-0800" aria-label="Permalink to &quot;[9.0.2] - 2021-09-25 UTC+0800&quot;">​</a></h2><h3 id="fixed-9" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-9" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Sometimes the value of the built-in variable <code>$waf_blocking_log</code> is wrong.</li></ul><hr><h2 id="_9-0-1-2021-09-24-utc-0800" tabindex="-1">[9.0.1] - 2021-09-24 UTC+0800 <a class="header-anchor" href="#_9-0-1-2021-09-24-utc-0800" aria-label="Permalink to &quot;[9.0.1] - 2021-09-24 UTC+0800&quot;">​</a></h2><h3 id="fixed-10" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-10" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Failed to load rules of ModSecurity.</li></ul><hr><h2 id="_9-0-0-2021-09-23-utc-0800" tabindex="-1">[9.0.0] - 2021-09-23 UTC+0800 <a class="header-anchor" href="#_9-0-0-2021-09-23-utc-0800" aria-label="Permalink to &quot;[9.0.0] - 2021-09-23 UTC+0800&quot;">​</a></h2><h3 id="note" tabindex="-1"><strong>NOTE</strong> <a class="header-anchor" href="#note" aria-label="Permalink to &quot;**NOTE**&quot;">​</a></h3><p>If you would like to upgrade to this version, please see the documentation for guidelines on upgrading across versions.</p><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>Compatible with <a href="https://github.com/SpiderLabs/ModSecurity" target="_blank" rel="noreferrer">ModSecurity</a>.</p></li><li><p>Added two directives: <code>waf_modsecurity</code> and <code>waf_modsecurity_transaction_id</code>.</p></li><li><p>Added parameter <code>MODSECURITY</code> to directive <code>waf_priority</code>.</p></li></ul><h3 id="removed-2" tabindex="-1">Removed <a class="header-anchor" href="#removed-2" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><p>Removed some parameters for directive <code>waf_mode</code>: <code>LIBINJECTION</code>, <code>LIBINJECTION-SQLI</code>, <code>LIBINJECTION-XSS</code> and <code>ADV</code>.</p></li><li><p>Removed the parameter <code>ADV</code> from the directive <code>waf_priority</code>.</p></li><li><p>Removed dependency <a href="https://github.com/libinjection/libinjection" target="_blank" rel="noreferrer">libinjection</a>.</p></li></ul><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li><p>No longer returns a 404 status code when the captcha succeeds, but a 204 status code instead.</p></li><li><p>Sometimes a complete inspection of the request body is not performed.</p></li></ul><hr><h2 id="_8-0-3-2021-08-27-utc-0800" tabindex="-1">[8.0.3] - 2021-08-27 UTC+0800 <a class="header-anchor" href="#_8-0-3-2021-08-27-utc-0800" aria-label="Permalink to &quot;[8.0.3] - 2021-08-27 UTC+0800&quot;">​</a></h2><h3 id="fixed-11" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-11" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Memory leak.</p></li><li><p>A field of a structure is not initialized, so you will see a lot of <code>malloc(size) failed (12: Out of memory)</code> in the error log.</p></li></ul><hr><h2 id="_8-0-2-2021-08-27-utc-0800" tabindex="-1">[8.0.2] - 2021-08-27 UTC+0800 <a class="header-anchor" href="#_8-0-2-2021-08-27-utc-0800" aria-label="Permalink to &quot;[8.0.2] - 2021-08-27 UTC+0800&quot;">​</a></h2><h3 id="fixed-12" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-12" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>nginx crashes(segmentation fault) after enabling CAPTCHA because the directive <code>waf_captcha</code> was not properly merged with different contexts.</p></li><li><p>CAPTCHA page cannot be displayed because the directive <code>waf_captcha</code> was not properly merged with different contexts.</p></li><li><p>If the directive <code>proxy_pass</code> is used, neither Under-Attack-Mode nor CAPTCHA will work properly.</p></li></ul><hr><h2 id="_8-0-1-2021-08-23-utc-0800" tabindex="-1">[8.0.1] - 2021-08-23 UTC+0800 <a class="header-anchor" href="#_8-0-1-2021-08-23-utc-0800" aria-label="Permalink to &quot;[8.0.1] - 2021-08-23 UTC+0800&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>No longer generates additional response headers when CC protection returns the status code 444.</li></ul><h3 id="fixed-13" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-13" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Segmentation fault when <code>User-Agent</code> is empty.</p></li><li><p>The directive <code>waf_http_status</code> could not be merged correctly.</p></li></ul><hr><h2 id="_8-0-0-2021-08-21-utc-0800" tabindex="-1">[8.0.0] - 2021-08-21 UTC+0800 <a class="header-anchor" href="#_8-0-0-2021-08-21-utc-0800" aria-label="Permalink to &quot;[8.0.0] - 2021-08-21 UTC+0800&quot;">​</a></h2><h3 id="note-1" tabindex="-1"><strong>NOTE</strong> <a class="header-anchor" href="#note-1" aria-label="Permalink to &quot;**NOTE**&quot;">​</a></h3><p>If you would like to upgrade to this version, please see the documentation for guidelines on upgrading across versions.</p><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>Introduced CAPTCHAs for third-party platforms, supporting hCaptcha, reCAPTCHAv2 and reCAPTCHAv3, with the associated directive <code>waf_captcha</code>.</p></li><li><p>Support recognizing friendly crawlers, including GooleBot, BingBot, BaiduSpider and YandexBot, and automatically allow them after successful recognition, the related command is <code>waf_verify_bot</code>.</p></li><li><p>CC protection supports enabling CAPTCHA mode, which enables CAPTCHA when the request rate exceeds the limit, and blocks the IP if the CAPTCHA fails three times in a row, and recounts the request rate on the contrary.</p></li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p>The syntax of the directive <code>waf_mode</code> has changed, see the documentation for a guide to cross-version upgrades.</p></li><li><p>The syntax of the directive <code>waf_cc_deny</code> has changed, see the documented guide to cross-version upgrades for details.</p></li><li><p>The syntax of the directive <code>waf_cache</code> has been changed, see the cross-version upgrade guide in the documentation.</p></li><li><p>Support for modifying the priority of request body inspection.</p></li></ul><h3 id="removed-3" tabindex="-1">Removed <a class="header-anchor" href="#removed-3" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Removed two parameters of the directive <code>waf_cache</code>: <code>interval</code> and <code>percent</code>.</li></ul><hr><h2 id="_7-1-0-2021-08-16-utc-0800" tabindex="-1">[7.1.0] - 2021-08-16 UTC+0800 <a class="header-anchor" href="#_7-1-0-2021-08-16-utc-0800" aria-label="Permalink to &quot;[7.1.0] - 2021-08-16 UTC+0800&quot;">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>The parameter <code>rate</code> of the directive <code>waf_cc_deny</code> allows more formats, such as <code>500r/s</code>, <code>500r/60s</code>, <code>500r/m</code>, <code>500r/60m</code>, <code>500r/h</code>, <code>500r/60h</code> and <code>500r/d</code>.</li></ul><hr><h2 id="_7-0-1-2021-08-11-utc-0800" tabindex="-1">[7.0.1] - 2021-08-11 UTC+0800 <a class="header-anchor" href="#_7-0-1-2021-08-11-utc-0800" aria-label="Permalink to &quot;[7.0.1] - 2021-08-11 UTC+0800&quot;">​</a></h2><h3 id="fixed-14" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-14" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Failed to parse <code>0.0.0.0/0</code> correctly when handling IP black and white lists.</p></li><li><p>Compatible with environments that do not support IPV6.</p></li></ul><hr><h2 id="_7-0-0-2021-08-04-utc-0800" tabindex="-1">[7.0.0] - 2021-08-04 UTC+0800 <a class="header-anchor" href="#_7-0-0-2021-08-04-utc-0800" aria-label="Permalink to &quot;[7.0.0] - 2021-08-04 UTC+0800&quot;">​</a></h2><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p>Changed the way Under Attack Mode is implemented. It is no longer implemented using redirects, but by modifying the response body.</p></li><li><p>Removed directive <code>uri</code> from configuration item <code>waf_under_attack</code>, see documentation for details.</p></li><li><p>Added a directive <code>file</code> to the configuration item <code>waf_under_attack</code> whose value should be the absolute path to an HTML file, see the documentation for details.</p></li><li><p>The directive <code>waf_cc_deny</code> is not allowed at the context <code>http</code>。</p></li></ul>',114)])])}const f=a(o,[["render",r]]);export{p as __pageData,f as default};
